import collections

MOD = 61

def count_solutions():
    # Count occurrences of x^2 mod 61
    squares = collections.Counter()
    for x in range(1, MOD + 1):
        squares[(x*x) % MOD] += 1

    # Count occurrences of x^3 mod 61
    cubes = collections.Counter()
    for x in range(1, MOD + 1):
        cubes[(x*x*x) % MOD] += 1

    # Count pairs (a, b) such that a^2 + b^2 = k mod 61
    sum_sq = collections.Counter()
    for s1, c1 in squares.items():
        for s2, c2 in squares.items():
            sum_sq[(s1 + s2) % MOD] += c1 * c2

    # Count pairs (c, d) such that d^3 - c^3 = k mod 61
    diff_cubes = collections.Counter()
    for c3, count_c in cubes.items():
        for d3, count_d in cubes.items():
            diff_cubes[(d3 - c3) % MOD] += count_c * count_d

    total_solutions = 0
    for k in range(MOD):
        total_solutions += sum_sq[k] * diff_cubes[k]

    return total_solutions

print(count_solutions())

